const rimLight = new THREE.SpotLight(0xffaa55, 1.8);
rimLight.position.set(-8, 4, -12);
rimLight.lookAt(0, 0, 0);
rimLight.penumbra = 0.5;

scene.add(ambient, keyLight, fillLight, rimLight);

const starGeo = new THREE.BufferGeometry();
const starCount = 4000;
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++) {
  starPos[i] = (Math.random() - 0.5) * 180;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.12, transparent: true, opacity: 0.9 });
const starField = new THREE.Points(starGeo, starMat);
scene.add(starField);

const apolloGroup = new THREE.Group();
scene.add(apolloGroup);

const goldFoilMat = new THREE.MeshPhysicalMaterial({
  color: 0xcfb53b,
  metalness: 0.85,
  roughness: 0.35,
  clearcoat: 0.6,
  clearcoatRoughness: 0.25,
  reflectivity: 0.8,
  side: THREE.DoubleSide
});

const silverMat = new THREE.MeshStandardMaterial({
  color: 0xd4d4d4,
  metalness: 0.75,
  roughness: 0.25
});

const heatShieldMat = new THREE.MeshStandardMaterial({
  color: 0x080808,
  roughness: 0.95,
  metalness: 0.1
});

const windowMat = new THREE.MeshPhysicalMaterial({
  color: 0x000000,
  metalness: 0.9,
  roughness: 0.05,
  clearcoat: 1.0
});

const cmLathePoints = [];
for (let i = 0; i <= 32; i++) {
  const t = i / 32;
  const angle = t * Math.PI * 0.48;
  const r = Math.sin(angle) * 1.9;
  const y = Math.cos(angle) * 1.9 + 0.4;
  cmLathePoints.push(new THREE.Vector2(r * 0.55, y * 0.55));
}
const cmGeo = new THREE.LatheGeometry(cmLathePoints, 64);
const cmMesh = new THREE.Mesh(cmGeo, silverMat);
cmMesh.castShadow = true;
cmMesh.receiveShadow = true;
apolloGroup.add(cmMesh);

const heatShieldGeo = new THREE.SphereGeometry(1.05, 64, 32, 0, Math.PI * 2, 0, Math.PI * 0.35);
const heatShield = new THREE.Mesh(heatShieldGeo, heatShieldMat);
heatShield.rotation.x = Math.PI;
heatShield.position.y = 0.05;
heatShield.castShadow = true;
apolloGroup.add(heatShield);

const smLength = 3.6;
const smRadius = 0.9;
const smGeo = new THREE.CylinderGeometry(smRadius, smRadius, smLength, 64);
const smMesh = new THREE.Mesh(smGeo, goldFoilMat);
smMesh.position.y = -smLength / 2 - 0.85;
smMesh.castShadow = true;
smMesh.receiveShadow = true;
apolloGroup.add(smMesh);

for (let i = 0; i < 4; i++) {
  const panelGeo = new THREE.BoxGeometry(0.12, smLength * 0.75, 0.08);
  const panel = new THREE.Mesh(panelGeo, goldFoilMat);
  const angle = (i / 4) * Math.PI * 2 + Math.PI / 4;
  panel.position.set(
    Math.cos(angle) * (smRadius + 0.04),
    smMesh.position.y,
    Math.sin(angle) * (smRadius + 0.04)
  );
  panel.lookAt(0, smMesh.position.y, 0);
  apolloGroup.add(panel);
}

const engineBellGeo = new THREE.ConeGeometry(0.35, 0.6, 32, 1, true);
const engineBell = new THREE.Mesh(engineBellGeo, new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.7 }));
engineBell.position.y = -smLength / 2 - 0.85 - smLength / 2 - 0.3;
apolloGroup.add(engineBell);

const glowLight = new THREE.PointLight(0xff4400, 0.8, 4);
glowLight.position.y = -2.8;
apolloGroup.add(glowLight);

[0, Math.PI / 2, Math.PI, Math.PI * 1.5].forEach((angle) => {
  const cluster = new THREE.Group();
  cluster.position.set(Math.cos(angle) * 0.75, 0.2, Math.sin(angle) * 0.75);
  cluster.lookAt(0, 0.2, 0);
  for (let r = 0; r < 4; r++) {
    const thruster = new THREE.Mesh(
      new THREE.CylinderGeometry(0.035, 0.035, 0.12, 8),
      silverMat
    );
    thruster.rotation.x = Math.PI / 2;
    thruster.position.set((r % 2) * 0.08 - 0.04, Math.floor(r / 2) * 0.08 - 0.04, 0.04);
    cluster.add(thruster);
  }
  apolloGroup.add(cluster);
});

const windowGeo = new THREE.CircleGeometry(0.08, 16);
[0, Math.PI * 2 / 3, Math.PI * 4 / 3].forEach((angle) => {
  const win = new THREE.Mesh(windowGeo, windowMat);
  const r = 0.5;
  win.position.set(Math.cos(angle) * r, 0.6, Math.sin(angle) * r);
  win.lookAt(0, 0.6, 0);
  win.rotateY(Math.PI);
  apolloGroup.add(win);
});

const antennaGroup = new THREE.Group();
antennaGroup.position.set(1.1, -1.4, 0);
antennaGroup.rotation.z = Math.PI / 2.5;
antennaGroup.rotation.y = Math.PI / 6;
apolloGroup.add(antennaGroup);

const boom = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 1.2, 8), silverMat);
boom.position.y = 0.6;
antennaGroup.add(boom);

const dishGeo = new THREE.CylinderGeometry(0.35, 0.08, 0.08, 32, 1, false, 0, Math.PI);
const dish = new THREE.Mesh(dishGeo, goldFoilMat);
dish.position.y = 1.2;
dish.rotation.x = 0.2;
antennaGroup.add(dish);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 20;

camera.position.set(5.5, 2.0, 6.5);
camera.lookAt(0, -0.5, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  apolloGroup.rotation.y = t * 0.08;
  apolloGroup.rotation.z = Math.sin(t * 0.05) * 0.03;
  apolloGroup.position.y = Math.sin(t * 0.3) * 0.08;

  antennaGroup.rotation.y = Math.sin(t * 0.5) * 0.2;

  rimLight.intensity = 1.5 + Math.sin(t * 1.1) * 0.4;
  glowLight.intensity = 0.6 + Math.sin(t * 3.0) * 0.2;

  starField.rotation.y = t * 0.005;

  controls.update();
  renderer.render(scene, camera);
}

animate();
